const publicSettingsDomainsToCheck = `-- name: PublicSettingsDomainsToCheck :many
SELECT workspace_id, custom_domain::text AS custom_domain, domain_status
FROM public_page_settings
WHERE custom_domain IS NOT NULL
  AND (domain_status IN ('pending','failed') OR domain_checked_at IS NULL OR domain_checked_at < $1)
`

type PublicSettingsDomainsToCheckRow struct {
	WorkspaceID  uuid.UUID `json:"workspaceId"`
	CustomDomain string    `json:"customDomain"`
	DomainStatus string    `json:"domainStatus"`
}

// Domains waiting for DNS (every run) and verified ones (once a day).
func (q *Queries) PublicSettingsDomainsToCheck(ctx context.Context, before *time.Time) ([]PublicSettingsDomainsToCheckRow, error) {
	rows, err := q.db.Query(ctx, publicSettingsDomainsToCheck, before)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PublicSettingsDomainsToCheckRow{}
	for rows.Next() {
		var i PublicSettingsDomainsToCheckRow
		if err := rows.Scan(&i.WorkspaceID, &i.CustomDomain, &i.DomainStatus); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

